CREATE TABLE IF NOT EXISTS dos.evidences (
  evidence_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id VARCHAR(16) NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  control_id UUID,
  file_url TEXT,
  file_type VARCHAR(50),
  status VARCHAR(50) NOT NULL DEFAULT 'pending',
  collected_by VARCHAR(64),
  reviewed_by VARCHAR(64),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  deleted_at TIMESTAMPTZ,
  is_deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX IF NOT EXISTS idx_evidences_tenant ON dos.evidences (tenant_id);

CREATE INDEX IF NOT EXISTS idx_evidences_control ON dos.evidences (control_id);
